    c3_notsuicide: [
      { n: { en: "Suppose Tom added the medicine himself. He then cleaned the empty bottle, despite his shaking hands, and returned it to a sooty pocket.", vi: "Giả sử Tom tự thêm thuốc. Rồi dù tay run, ông lau sạch lọ rỗng và cất lại vào một túi áo đầy muội." } },
      { n: { en: "Possible. But it leaves a lot unexplained.", vi: "Có thể. Nhưng như thế vẫn còn nhiều điều chưa giải thích được." } },
      { n: { en: "Fergus filled the flask at nine. Tom could have emptied some later. The full flask alone proves nothing.", vi: "Chín giờ Fergus rót đầy bình. Tom có thể đã đổ bớt đi sau đó. Chỉ riêng việc bình đầy chưa chứng minh được gì." } },
      { n: { en: "But somebody rinsed the TOM bottle while the boat was out. Why clean the source, if Tom only dosed his own flask?", vi: "Nhưng có người xả chai TOM trong lúc xuồng ra khơi. Vì sao phải rửa chai nguồn, nếu Tom chỉ bỏ thuốc vào bình riêng?" } },
      // Cờ lõi giữ tên cũ: giả thuyết đủ để điều tra, không thay cho xét nghiệm.
      { set: { p_not_suicide: true, p_bottle_route: true } },
      { show: "leo", at: "c", face: "cold" },
      { say: "me", en: "The medicine could already have been in the whisky. The clean vial could have been planted.", vi: "Thuốc có thể đã ở sẵn trong rượu. Lọ sạch có thể đã bị bỏ vào túi để dựng chuyện." },
      { n: { en: "Leo looks at the bags for a long time. Then at the back-room door, where the whisky bottle with its ruined label is locked away.", vi: "Leo nhìn mấy cái túi rất lâu. Rồi nhìn cánh cửa phòng trong, nơi cái chai whisky với tấm nhãn đã hỏng đang bị khóa kín." }, on: "leo" },
      { say: "leo", face: "sad", tone: "quiet, newly alert", en: "Then we can't treat this as suicide.", vi: "Vậy thì chúng ta không thể coi đây là tự tử." },
      { say: "leo", tone: "practical, controlled", en: "CID will test the bottle and the flask. We keep every sample.", vi: "Bên điều tra sẽ xét nghiệm chai và bình rượu. Chúng ta giữ lại mọi mẫu." },
      { n: { en: "He says it quietly, to the table, as if he'd rather not have heard it.", vi: "Anh nói khẽ, mắt nhìn xuống bàn, như thể anh thà không phải nghe điều đó." }, on: "leo" },
      { note: { en: "Working theory: the TOM whisky may have been tampered with before Fergus poured it. The rinsed bottle and clean vial need investigation and tests.", vi: "Giả thuyết: chai whisky TOM có thể đã bị can thiệp trước khi Fergus rót. Chai bị xả nước và lọ sạch cần được điều tra, xét nghiệm." } },
      { go: "c3_out" },
    ],

    // ── 00:15 · Leo thả bạn (giữ chìa khóa) — Helen dưới đèn bến
    c3_out: [
      { clock: "00:15" },
      { if: s => s.f.leo_id === "lie" || s.f.took_draft, then: [
        { n: { en: "Quarter past twelve. Leo doesn't get up. He just tips his chin at the door. The cold comes in off the water.", vi: "Mười hai giờ mười lăm. Leo không đứng dậy. Anh chỉ hất cằm về phía cửa. Hơi lạnh từ mặt nước tràn vào." }, on: "leo" },
      ], else: [
        { n: { en: "Quarter past twelve. Leo opens the door for you. The cold comes in off the water.", vi: "Mười hai giờ mười lăm. Leo mở cửa cho bạn. Hơi lạnh từ mặt nước tràn vào." }, on: "leo" },
      ] },
      { say: "leo", en: "Stay near the harbour. If you remember anything else, come straight back.", vi: "{Ac} cứ ở gần bến nhé. Nhớ ra điều gì khác thì quay lại đây ngay." },
      { say: "me", en: "My keys?", vi: "Chìa khóa xe của tôi?" },
      { say: "leo", en: "They stay with me for now.", vi: "Tạm thời tôi giữ." },
      { hide: "*" },
      { bg: "harbour" }, { amb: "sea" }, { mood: "cold" },
      { n: { en: "You step out onto the harbour wall. Behind you, the door closes on the light and the kettle and the man in the back room.", vi: "Bạn bước ra tường chắn sóng. Sau lưng bạn, cánh cửa khép lại, giấu đi ánh đèn, cái ấm nước, và người đàn ông ở phòng trong." } },
      { n: { en: "A car is parked under the harbour lamp with its engine off. Someone is standing beside it, arms wrapped round herself.", vi: "Một chiếc xe đỗ dưới ngọn đèn bến, máy đã tắt. Một người phụ nữ đứng cạnh xe, hai tay ôm lấy mình." } },
      { cg: "harbour-lamp" }, { cam: "pull", ms: 8000 },
      { show: "helen", at: "c", face: "scared" },
      { n: { en: "Dr Vosper. Her face is the colour of the lamp.", vi: "Bác sĩ Vosper. Mặt bà cùng một màu với ngọn đèn." }, on: "helen" },
      { cam: null },
      { say: "helen", face: "scared", en: "Can I talk to you? Not him. You.", vi: "Tôi nói chuyện với {ac} được không? Không phải với anh ta. Với {ac}." },
      { hide: "*" }, { cg: null }, { cam: null }, { mood: null },
      { end: "c3_end" },
    ],
